//! Checks the SDK's pubkey-account derivation and transaction preimages
//! against the shared cross-language vectors.
//!
//! `data/pubkey_auth.json` is a verbatim copy of thruput-protocol's
//! `test_vectors/pubkey_auth.json` (generated by its Go generator). Refresh
//! it from there rather than editing it; a disagreement here is a
//! cross-implementation bug to report, not a vector to patch.

use serde_json::Value;
use thruput_domain_separator::sha2::{
    pubkey_account_address, public_key_hash,
};
use thruput_domain_separator::{
    PUBKEY_ACCOUNT, PUBLIC_KEY, Sha2, Sha256Backend, TRANSACTION,
    transaction_signature_preimage,
};
use thruput_xdr::auth_claim::{AuthClaim, PubkeyAccountPreimage};
use thruput_xdr::transaction::{SignedTransaction, Transaction};
use thruput_xdr::types::{NetworkHash, PublicKey, PublicKeyHash};

fn vectors() -> Value {
    serde_json::from_str(include_str!("data/pubkey_auth.json"))
        .expect("pubkey_auth.json parses")
}

fn unhex(v: &Value) -> Vec<u8> {
    let s = v.as_str().expect("hex string");
    assert!(s.len().is_multiple_of(2), "odd-length hex");
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex digit"))
        .collect()
}

fn unhex32(v: &Value) -> [u8; 32] {
    unhex(v).try_into().expect("32 bytes")
}

fn by_name<'a>(list: &'a Value, name: &str) -> &'a Value {
    list.as_array()
        .unwrap()
        .iter()
        .find(|e| e["name"] == name)
        .unwrap_or_else(|| panic!("no entry named {name}"))
}

#[test]
fn domain_separators_match() {
    let v = vectors();
    let ds = &v["domain_separators"];
    assert_eq!(
        unhex(&ds["PubkeyAccount"]["cxs"]),
        PUBKEY_ACCOUNT.as_bytes()
    );
    assert_eq!(unhex(&ds["PublicKey"]["cxs"]), PUBLIC_KEY.as_bytes());
    assert_eq!(unhex(&ds["Transaction"]["cxs"]), TRANSACTION.as_bytes());
}

#[test]
fn keys_and_addresses_match() {
    let v = vectors();
    let keys = v["keys"].as_array().unwrap();
    assert!(keys.iter().any(|k| k["scheme"] == "Ed25519"));
    assert!(keys.iter().any(|k| k["scheme"] == "MlDsa65"));

    for key in keys {
        let name = key["name"].as_str().unwrap();
        let pk: PublicKey = xdrs::cxs::decode(&unhex(&key["public_key_cxs"]))
            .unwrap_or_else(|e| panic!("{name}: decode key: {e:?}"));
        assert_eq!(
            pk.scheme().0 as u64,
            key["scheme_value"].as_u64().unwrap(),
            "{name}: scheme"
        );
        assert_eq!(
            xdrs::txs::encode(&pk).unwrap(),
            unhex(&key["public_key_xdr"]),
            "{name}: XDR encoding"
        );

        let hash = public_key_hash(&pk);
        assert_eq!(
            hash,
            PublicKeyHash::new(unhex32(&key["public_key_hash"])),
            "{name}: public key hash"
        );

        for account in key["accounts"].as_array().unwrap() {
            let nonce: u64 =
                account["nonce"].as_str().unwrap().parse().unwrap();
            let preimage = PubkeyAccountPreimage {
                pubkey_hash: hash,
                nonce,
            };
            assert_eq!(
                xdrs::cxs::encode(&preimage).unwrap(),
                unhex(&account["pubkey_account_preimage_cxs"]),
                "{name}/{nonce}: preimage CXS"
            );
            assert_eq!(
                pubkey_account_address(&preimage).into_inner(),
                unhex32(&account["address"]),
                "{name}/{nonce}: address"
            );
        }
    }
}

/// Decode a signed transaction and check what this SDK can check without a
/// verifier: the encoding round-trips, the transaction hash, and that the
/// claim key hashes to the claim's `pubkey_hash`.
fn check_signed(
    name: &str,
    stx_xdr: &Value,
    tx_hash: &Value,
) -> SignedTransaction {
    let bytes = unhex(stx_xdr);
    let stx: SignedTransaction = xdrs::txs::decode(&bytes)
        .unwrap_or_else(|e| panic!("{name}: decode signed tx: {e:?}"));
    assert_eq!(xdrs::txs::encode(&stx).unwrap(), bytes, "{name}: re-encode");
    assert_eq!(
        Sha2::sha256(&xdrs::txs::encode(&stx.tx).unwrap()),
        unhex32(tx_hash),
        "{name}: transaction hash"
    );
    let AuthClaim::kPubkeySignature { pubkey_preimage } = &stx.tx.auth_claim
    else {
        panic!("{name}: expected a kPubkeySignature claim");
    };
    let key = stx.pubkey_claim_key.as_ref().expect("claim key present");
    assert_eq!(public_key_hash(key), pubkey_preimage.pubkey_hash, "{name}");
    assert_eq!(stx.signatures.len(), 1, "{name}: one signature");
    stx
}

#[test]
fn signing_cases_match() {
    let v = vectors();
    let keys = &v["keys"];
    for case in v["signing"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let tx_bytes = unhex(&case["transaction_xdr"]);
        let tx: Transaction = xdrs::txs::decode(&tx_bytes)
            .unwrap_or_else(|e| panic!("{name}: decode tx: {e:?}"));
        assert_eq!(xdrs::txs::encode(&tx).unwrap(), tx_bytes, "{name}");

        let network = NetworkHash::new(unhex32(&case["network_hash"]).into());
        assert_eq!(
            transaction_signature_preimage(&network, &tx).unwrap(),
            unhex(&case["signing_preimage"]),
            "{name}: signing preimage"
        );

        let stx = check_signed(
            name,
            &case["signed_transaction_xdr"],
            &case["transaction_hash"],
        );
        assert_eq!(stx.tx, tx, "{name}: signed tx carries the same tx");

        // The claim names the vector's key, and the invoked address is that
        // key's account at the claim's nonce.
        let key = by_name(keys, case["key"].as_str().unwrap());
        assert_eq!(
            xdrs::cxs::encode(stx.pubkey_claim_key.as_ref().unwrap()).unwrap(),
            unhex(&key["public_key_cxs"]),
            "{name}: claim key"
        );
        let AuthClaim::kPubkeySignature { pubkey_preimage } = &tx.auth_claim
        else {
            unreachable!()
        };
        assert_eq!(
            pubkey_account_address(pubkey_preimage),
            tx.invocation.invoked_address,
            "{name}: invoked address is the claim's account"
        );
    }
}

/// Re-signing changes the signature but not the transaction or its hash.
#[test]
fn resigning_keeps_transaction_hash() {
    let v = vectors();
    for case in v["resigning"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let base = by_name(&v["signing"], case["of"].as_str().unwrap());
        let stx = check_signed(
            name,
            &case["signed_transaction_xdr"],
            &case["transaction_hash"],
        );
        assert_eq!(case["transaction_hash"], base["transaction_hash"]);
        assert_eq!(
            xdrs::txs::encode(&stx.tx).unwrap(),
            unhex(&base["transaction_xdr"]),
            "{name}"
        );
        assert_ne!(
            case["signed_transaction_xdr"], base["signed_transaction_xdr"],
            "{name}: a re-signature differs"
        );
    }
}

/// Negative cases must still decode: rejecting them is the verifier's job,
/// not the decoder's.
#[test]
fn negative_cases_decode() {
    let v = vectors();
    for case in v["negative"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let bytes = unhex(&case["signed_transaction_xdr"]);
        let stx: SignedTransaction = xdrs::txs::decode(&bytes)
            .unwrap_or_else(|e| panic!("{name}: decode: {e:?}"));
        assert_eq!(xdrs::txs::encode(&stx).unwrap(), bytes, "{name}");
        assert_eq!(
            Sha2::sha256(&xdrs::txs::encode(&stx.tx).unwrap()),
            unhex32(&case["transaction_hash"]),
            "{name}: transaction hash"
        );
    }
}
